internal object DuaKokDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_q_lut_najjini_ahli" to DuaText("दुआ ऑफ लूत (ए. एस.)-सेव्ह माय फॅमिली", "म्हज्या देवा, म्हाका आनी म्हज्या कुटुंबाक ते जे करतात ताचे (परिणाम) पसून वाटाव.", "वायट वातावरणांतल्यान आपल्या कुटुंबाची राखण करप.", "कुटुंबाचें वायटपणासावन रक्षण करचें."),
        "dua_q_sulaiman_awzini" to DuaText("सुलेमानाचो दुआ (ए. एस.) उपकार मानपी खातीर", "म्हज्या प्रभू, तूं म्हाका आनी म्हज्या आवय-बापायक दिल्ल्या उपकारा खातीर म्हाका उपकार मानपाक, आनी तुका प्रसन्न करपी धर्मीक कामां करपाक, आनी तुज्या दयाळ्यान म्हाका तुज्या धर्मीक सेवकां मदीं प्रवेश दिवपाक सक्षम कर.", "आशीर्वादां खातीर उपकार मानपाच्या तांकी खातीर.", "सुलेमानाची (ए. एस.) उपकाराची दुआ."),
        "dua_q_musa_zalamtu" to DuaText("मुसाचो दुआ (ए. एस.)-हांवें स्वताचेर अन्याय केलो", "म्हज्या प्रभू, हांवें स्वताचेर अन्याय केला, देखून म्हाका माफ कर.", "चुक जातकच रोखडोच पश्चात्ताप करचो.", "अल्लाहान मूसाक (अ. स.) माफ केलो."),
        "dua_q_musa_najjini" to DuaText("मुसाचो दुआ (ए. एस.)-म्हाका अत्याचारी पसून वाटाव", "म्हज्या देवा, म्हाका दुष्ट लोकां पसून वाटाव.", "जुलमी लोकांक भियेतना.", "इजिप्त सोडतना मुसाचो (ए. एस.) दुआ."),
        "dua_q_lut_unsurni" to DuaText("लूत (ए. एस.)-भ्रष्टाचारा आड मदत", "म्हज्या देवा, भ्रष्ट लोकां आड म्हाका मदत कर.", "भ्रष्टाचार पसरयल्ल्यां आड मदत करपा खातीर.", "सत्याचेर ठाम रावपी लोकांची दुआ."),
        "dua_q_hab_li_salihin" to DuaText("इब्राहिम (ए. एस.) हाचो दुआ एका धर्मीक भुरग्या खातीर", "म्हज्या देवा, म्हाका (भुरगें) धर्मीक लोकां मदल्यान दिवचें.", "धर्मीक भुरगीं मागप.", "हाचे वरवीं दुआ इस्मायील (ए. एस.) मेळ्ळो."),
        "dua_q_wasita_kulla_shay" to DuaText("सिंहासन धारण करपी दूतांचो दुआ", "म्हज्या देवा, तूं सगळ्या गजालींक दयाळू आनी गिन्यानान घेरता, देखून पश्चात्ताप करपी आनी तुज्या मार्गाचेर चलपी लोकांक माफ कर, आनी नरक शिक्षे पसून तांची राखण कर.", "सिंहासन धारण करपी देवदूतांनी श्रद्धावानां खातीर ही दुआ तयार करतात.", "देवदूतांच्या दुआत आस्पाव करपाच्या हेतान पठण केलें."),
        "dua_q_ikhwanina" to DuaText("आमचे पयलीं आशिल्ल्या भावांक", "म्हज्या प्रभू, आम्हांक आनी आमचे आदीं विश्वास दवरिल्ल्या भावांक माफ कर, आनी जे विश्वास दवरतात तांचे कडेन आमच्या काळजांत राग घालचो न्हय. आमच्या प्रभू, तूं खरेंच दयाळू आनी दयाळू आसा.", "पयलीं आनी नितळ काळजा खातीर आयिल्ल्या श्रद्धावंत लोकां खातीर एक दुआ.", "कुलीन साथीदारांक (आर. ए.) आनी आदल्या श्रद्धावंतांक एक दुआ."),
        "dua_q_alayka_tawakkalna" to DuaText("तुजेचेर आमी विस्वास दवरतात (इब्राहिम ए. एस.)", "म्हज्या प्रभू, आमी तुज्याचेर भरवंसा दवरतात, तुजे वटेन वळटात आनी तुजे वटेन परत येता. हे म्हज्या प्रभू, आम्हांक काफ़िर लोकांखातीर चांचणी करची न्हय आनी आम्हांक माफ कर. हे म्हज्या प्रभू, तूं खरेंच प्रभुत्ववान, तत्ववान आसा.", "इब्राहिम (अ. स.) आनी ताच्या साथीदारांचो दुआ.", "अल्लाहाक आदारून रावपाची आनी ताचे वटेन वळपाची दुआ."),
        "dua_q_atmim_nurana" to DuaText("आमचो उजवाड परिपूर्ण कर", "म्हज्या प्रभू, आमचो उजवाड आमच्यासाठी परिपूर्ण कर आनी आमकां माफ कर. खरें म्हणल्यार तूं सगळ्या गजालींचेर सामर्थ्यवान आसा.", "पुनरुत्थान दिसा श्रद्धावंतांची दुआ.", "सिराताचेर उजवाड दिवपाची मागणी."),
        "dua_q_asiya_baytan" to DuaText("आसियाचो दुआ-जन्नांतलें एक घर", "म्हज्या प्रभू, म्हजे खातीर तुझ्या लागसार स्वर्गांत एक घर बांदाव, म्हाका फारो आनी ताच्या कामां पसून वाटाव, आनी म्हाका अन्याय करपी लोकां पसून वाटाव.", "आसियाची दुआ, फारोची बायल.", "अल्लाहान तिका श्रद्धावानां खातीर एक देख केली."),
        "dua_adhan_response" to DuaText("अधानाक जाप दिवप", "अल्लाह सोडून कोणूच सामर्थ्य वा शक्ती ना.", "मुएझिन कितें म्हणटा तें परतून सांग;'हय्या'अलास-सालाह'आनी'हय्या'अलाल-फालाह'हातूंत अशें म्हणात.", "जो मनांतल्यान प्रतिसाद दितलो तो स्वर्गांत प्रवेश करतलो."),
        "dua_adhan_shahadah" to DuaText("मुअज्जिनांच्या शहादा उपरांत", "आनी हांव लेगीत साक्षी दिता की एकलो, एकलो, भागीदार नासतना, अल्लाह सोडून कोणाच्याकूय पुजा करपाचो अधिकार ना आनी मुहंमद सल्ल्यल्लाह इस्लाम ताचो सेवक आनी संदेशवाहक आसा. हांव अल्लाहाक प्रभु म्हूण, मुहंमद सल्ल्याह अल्लीमाक संदेशवाहक म्हूण आनी इस्लामाक धर्म म्हूण प्रसन्न आसा.", "मुएझीनाची श्रद्धेची साक्ष आयकून.", "ताच्या पापांची माफी मेळटा."),
        "dua_istiftah_baid" to DuaText("दुआ उगडः म्हाका पापां पसून पयस कर", "हे अल्लाह, तूं उदेंतेक अस्तंतेसावन पयस दवरला म्हणून म्हाका म्हज्या पापां पसून पयस कर. हे अल्लाह, धवे वस्त्रां घाणीं निवळ जातात अशे म्हजें पाप निवळ कर. हे अल्लाह, उदक, बर्फ आनी गारपांनी म्हजें पाप धुव.", "उक्तावल्या उपरांत तकबीर (सनाच्या जाग्यार लेगीत अशें म्हणूं येता).", "पैगंबर सल्ल्युल्लाह अलियाह वसलमान ताकबीर आनी पठण हांचे मदीं हें पठण केलें."),
        "dua_hamdan_kathiran" to DuaText("रुकू उपरांत भरपूर तोखणाय", "म्हज्या देवा, तोखणाय तुजीच आसा-भरपूर, शुद्ध आनी आशीर्वादीत तोखणाय.", "रुकू सावन वयर सरल्या उपरांत'रब्बाना लकल-हमद \"वांगडा.", "तीस परस चड देवदूतांन तो पयलो रेकॉर्ड करपा खातीर सर्त करताले."),
        "dua_subbuhun_quddus" to DuaText("सुब्बूहुन कुद्दुस (रुकु आनी सुजूद)", "(अल्लाह) परम गौरवशाली, परमपवित्र, देवदूतांचो आनी आत्म्याचो (जिब्रिल) स्वामी.", "रुकू आनी सुजूदांत.", "पैगंबर सल्ल्याह अलियाह वसलमान हें रुकू आनी सुजूद भाशेंत पठिल्लें."),
        "dua_sujood_dhanbi_kullah" to DuaText("सुजूदः म्हज्या सगळ्या पापांक माफ कर.", "हे अल्लाह, म्हज्या सगळ्या पापांक-ल्हान आनी व्हड, पयलो आनी निमाणो, उक्ते आनी लुकोवन दवरिल्ले पापांक-म्हाका माफ कर.", "सुजूदांत.", "प्रोस्ट्रेशन ही एक सुवात जंय दुआक जाप दितात."),
        "dua_sujood_ridaka" to DuaText("तुज्या आनंदांत आश्रय घे", "हे अल्लाह, हांव तुज्या रागाक लागून तुज्या आनंदाक, तुज्या ख्यास्ताक लागून तुका माफ करपाक आलाशिरो मागता, आनी हांव तुज्या कडल्यान तुजे कडेन आलाशिरो मागता. हांव तुजी पुराय तोखणाय करूंक शकना; तूं स्वताची तोखणाय केल्या सारकोच आसा.", "सुजूदांत आयशा (रा.) हाणें पैगंबर सल्ल्याह अल्लीह वसीमाचें हें सांगप आयकून घेतलें.", "पैगंबर सल्ल्याह अल्लीह वसीमाचो एक सुजूद दुआ."),
        "dua_tashahhud" to DuaText("ताशाहहुद (अत-ताहिययात)", "सगळ्या मौखिक, शारिरीक आनी अर्थीक उपासनेच्यो कामां अल्लाहाक आसात. हे पैगंबर, तुमचेर शांती आसची, आनी अल्लाहची दया आनी ताचो आशीर्वाद आसचो. आमचेर आनी अल्लाहच्या धर्मीक सेवकांचेर शांती आसचो. अल्लाह सोडून कोणाकूय पुजा करपाचो अधिकार ना हाची हांव साक्षी दिता, आनी मुहंमद सल्ल्याह अल्लीह इस्लाम ताचो सेवक आनी संदेशवाहक आसा हाची हांव साक्ष दिता.", "दर एका बसकेंत-अब्दुल्ला इब्न मसूद (र.) (हनाफी प्रॅक्टिस) हाणें कथन केलां.", "पैगंबर सल्लल्लाह अलियाह वसलमान कुराणांतल्या सूरहा भशेन तें शिकयलें."),
        "dua_sajdah_tilawah" to DuaText("पठण साजदा", "ज्या जाणें तें निर्माण केलें आनी ताच्या सामर्थ्यान आनी शक्तीन ताची आयकुपाक आनी पळोवपाक हाडली ताका म्हजें तोंड नमस्कारा.", "पठण करतना.", "पैगंबर सल्ल्यल्लाह अलीह वस्लमान रातच्या पठणांत हें सांगलें."),
        "dua_after_witr" to DuaText("विटर उपरांत", "परमपवित्र राजाचो गौरव असो.", "विदरच्या सलामा उपरांत तीन फावटीं, तिसऱ्यां फावट आवाज उखलून.", "पैगंबर सल्ल्याह अलियाह वसलमान हे विदर उपरांत सांगलें."),
        "dua_tahajjud_nur" to DuaText("तहज्जुद उक्तावपाची विनवणी", "हे अल्लाह, तोखणाय तुजीच आसा; तूं स्वर्गांचो, धर्तरीचो आनी तातूंतल्या सगळ्याचो पालन करपी. तोखणाय तुजीच आसा. तूं स्वर्गांचो, धर्तरीचो आनी तातूंतल्या सगळ्याचो उजवाड. तोखणाय तुजीच आसा; तूं सत्य, तुजें उतर खरें, तुजी भेट खरें, तुजें वचन खरें, स्वर्ग खर, नरक खर, पयशवा सत्य, मुहंमद सल्लल्लाह अल्लाह इस्लाम खर आनी वेळ खर.", "रातची प्रार्थना (तहज्जुद) (दुआचो उक्तावपी भाग) सुरू करतना.", "पैगंबर सल्ल्युल्लाह अलियाह वसलमान तहज्जूदा खातीर उठतकच (पुराय दुआ अल-बुखारींत आसा) हें पठिल्लें."),
        "dua_rabba_jibrail" to DuaText("वादग्रस्त बाबतींत म्हाका मार्गदर्शन कर", "हे जिब्रिल, मीकाईल आनी इसराफिल ह्या आकाशांचो आनी धर्तऱ्याचो निर्माण करपी, नदर आनी दिश्टी हांचो जाणकार, अल्लाह! तुज्या सेवकां मदीं जे मतभेद आशिल्ले तातूंत तूं न्याय करचो. तुज्या परवानगीन म्हाका सत्या कडेन मार्ग दाखय. जे मतभेद आसात तातूंत. तूं कोणाक सरळ मार्ग दाखयता तें तूं दाखयता.", "तहज्जूदाच्या सुरवेक-मतभेद हांचे मदीं सत्याक मार्गदर्शन दिवपा खातीर.", "पैगंबर सल्ल्याह अलियाह वसलमान रातची प्रार्थना ह्या दुआन सुरू केली."),
        "dua_going_to_mosque_nur" to DuaText("मशिदीत वचप (उजवाडाचो दुआ)", "हे अल्लाह, म्हज्या काळजांत उजवाडा, म्हज्या दोळ्यांत उजवाडा, म्हज्या कानांत उजवाडा, म्हज्या उजव्या वटेन उजवाडा, म्हज्या दाव्या वटेन उजवाडा, म्हजे वयर उजवाडा, म्हजे सकयल उजवाडा, म्हज्या मुखार उजवाडा, म्हज्या फाटल्यान उजवाडा, आनी म्हजे खातीर उजवाडा कर.", "फजराक मशिदीत वचतना.", "पैगंबर सल्ल्यल्लाह अलीह वस्लमान प्रार्थनेंत भायर वचतना हें पठण केलें."),
        "dua_waswasa_salah" to DuaText("साल्हा वेळार वासवास (खिंझाब)", "शापित शयताना कडल्यान हांव अल्लाहाक आलाशिरो मागता.", "प्रार्थने वेळार सैतानाची कुजबुज येता तेन्ना आलाशिरो घेयात आनी तीन फावटीं दावे वटेन हळडुवें सुकून थुंको.", "उथमान इब्न अबील -'अस (रा.) हाणें हें केलें आनी कुजबुज पयस गेली."),
        "dua_alimal_ghayb" to DuaText("न दिसपी गजालींचें गिन्यान करपी", "हे अल्लाह, नदर आनी दिश्टीचें जाणकार, आकाश आनी धर्तरेचो निर्मातो, प्रभू आनी सगळ्या गजालींचो राजा! हांव साक्षी दिता की तुज्या शिवाय कोणूच देव ना. हांव म्हज्या स्वताच्या वायटपणांतल्यान, शयतनाच्या वायटपणांतल्यान आनी ताच्या शिर्कांतल्यान तुजो आलाशिरो मागता.", "सकाळ, सांज आनी न्हिदचे पयलीं-पैगंबर सल्ल्याह अलियाह वसलमान अबू बकराक (र.) तें शिकयलें.", "स्वताच्या आनी शयतनाच्या वायटपणासावन राखण."),
        "dua_fitratil_islam" to DuaText("इस्लाम धर्माच्या फित्राचेर", "आमी इस्लाम धर्माच्या फित्राक सकाळीं, प्रामाणीकपणाच्या उतरार, आमच्या पैगंबर मुहंमद सल्ल्याह अलीह् इस्लामाच्या धर्माचेर आनी आमचो बापूय इब्राहिम (ए. एस.) हाच्या मार्गान प्रवेश केला, जो निश्ठावान आनी मुसलमान आशिल्लो, आनी बहुदेववादी आशिल्लो ना.", "सकाळीं.", "दर सकाळीं स्वताचो विश्वास नव्यान घडयात."),
        "dua_amsayna_fitrah" to DuaText("इस्लाम धर्माच्या फित्राच्या दिसा सांज", "आमी इस्लाम धर्माच्या फित्राक सांजवेळार, प्रामाणीकपणाच्या उतरान, आमच्या पैगंबर मुहंमद सल्ल्याह अलीह् इस्लामाच्या धर्माचेर आनी आमचो बापूय इब्राहिम (ए. एस.) हाच्या मार्गान प्रवेश केला, जो निश्ठावान आनी मुसलमान आशिल्लो, आनी बहुदेववादी आशिल्लो ना.", "सांजवेळार.", "दर सांजीं स्वताचो विश्वास नव्यान घडयात."),
        "dua_tahleel_10_fajr" to DuaText("फजर आनी माघरीबा उपरांत धा तहलील", "अल्लाह सोडून कोणाकूच पुजा करपाचो अधिकार ना, एकलो, भागीदार नासतना. राजवट ताचीच आनी तोखणाय ताचीच; तो जिवीत दिता आनी मरण हाडटा, आनी ताका सगळ्या गजालींचेर अधिकार आसा.", "फजर (आनी माघरीब) उपरांत धा फावटीं, तुमचें बसप वा उलोवप सोडून वचचे पयलीं.", "धा बरे कामां, धा पापां काबार जालीं, धा पदां वाडयलीं आनी पुराय दीस शयतना पसून राखण मेळटली."),
        "dua_la_hawla_kanz" to DuaText("ए ट्रेझर ऑफ जन्ना", "अल्लाह सोडून कोणूच सामर्थ्य वा शक्ती ना.", "चड करून, सदांच.", "स्वर्गांतल्या खजिन्यां मदलो हो एक."),
        "dua_four_beloved_words" to DuaText("चार सगळ्यांत आवडट्या उतरां", "अल्लाहाक महिमा, सगळ्यो तोखणाय अल्लाहाक आसा, अल्लाह सोडून कोणाकूय पुजा करपाचो अधिकार ना, आनी अल्लाह सगळ्यांत व्हड आसा.", "अल्लाहाक सगळ्यांत चड आवडपी उतर.", "पैगंबर सल्लल्लाह अल्लीह ओस्लमाक सूर्य उगवपी सगळ्या गजालीं परस ते चड प्रिय आसात."),
        "dua_two_light_words" to DuaText("दोन उतरां जिभेचेर उजळट", "अल्लाहाक महिमा आनी सगळी तोखणाय ताचीच; महिमा महान अल्लाहाक.", "जीबेर हलकें, मापकेर जड.", "परम करुणामायकाक आवडटा, जीबेर हळडुवो आनी मापकेर जड. (अल-बुखारीची निमाणो हदीस)"),
        "dua_ya_dhal_jalal" to DuaText("या धल-जलाली वाल-इकराम", "हे म्हाजती आनी सन्मान मेळोवपी!", "पयशवाचें सल्ल्याह अल्लीह वसलम हें सुचोवणी-दुआत तें धरून दवरात.", "पैगंबर सल्लल्लाह अलीह वस्लमान सांगलेंः'या धाल-जलाली वाल-इकराम \"धरून दवर."),
        "dua_sleep_wadatu_janbi" to DuaText("तुज्या नांवान हांव न्हिदता.", "म्हज्या प्रभू, हांव तुज्या नांवान म्हजी बाजू दवरता आनी तुज्या नांवान हांव उठतां. तूं म्हजो जीव घेतल्यार ताचेर दया कर, आनी तूं ताका सोडल्यार तुज्या धर्मीक सेवकांची राखण करता तसो ताची राखण कर.", "खाटेचेर धूळ घालून न्हिदल्या उपरांत.", "न्हिदचे पयलीं आपलो आत्मा अल्लाहाक सोपोवप."),
        "dua_sleep_khalaqta_nafsi" to DuaText("तूं म्हजो आत्मा तयार केलो.", "हे अल्लाह, तूं म्हजो आत्मा निर्माण केलो आनी तूं तो घेयलो. ताचो मरण आनी ताचो जीव तुजो. जर तूं ताका जिवीत दवरलो जाल्यार ताची राखण कर, आनी जर तूं ताका मरयता जाल्यार ताका माफ कर. हे अल्लाह, हांव तुजे बरे खातीर मागता.", "न्हिदचे पयलीं-इब्न उमरान (र.) कथन केलां.", "पैगंबर सल्ल्याह अलियाह वसलमान न्हिदतना हें सांगपाचो आदेश दिलो."),
        "dua_sleep_atamana" to DuaText("न्हिदचे पयलीं उपकार मानचो", "सगळ्यो तोखणाय अल्लाहाक आसा, जो आमकां पोसयतालो, पिवयतालो, फावोसो आदार दितालो आनी आलाशिरो दितालो. कितले लोक आसात जांकां फावोशें ना वा तांकां आलाशिरो दिवंक ना.", "न्हिदतना.", "पैगंबर सल्ल्याह अलियाह वसलमान न्हिदतना हें सांगलें."),
        "dua_sleep_rabbas_samawat" to DuaText("स्वर्गांतलो स्वामी-आमचे रीण फारीक कर", "हे स्वर्गांचो, धर्तऱ्याचो आनी पराक्रमी सिंहासनाचो स्वामी, हो अल्लाह, हो आमचो प्रभू आनी सगळ्या गजालींचो स्वामी, बींचो आनी खजूराचो पिळपी, तोराह, इंजिल आनी फुरकान हांचो खुलासा करपी! तूं ज्या सगळ्या वायट गजालींचेर आगरो दवरता तातूंतलो हांव तुका आलाशिरो मागता. हे अल्लाह, तूं पयलो, तुझ्या मुखार कांयच ना; तूं निमाणो, तुझ्या उपरांत कांयच ना; तूंच सगळ्यांत चड प्रकट, तुज्या वयर कांयच ना, तूंच लपलेलो, तुजें कडल्यान कांयच लपलें ना. आमचे खातीर आमचे रिण थाराव आनी आमकां गरिबी पसून मुक्त कर.", "न्हिदचे पयलीं उजवे वटेन न्हिदप-फातिमाक (आर. ए.) शिकयलां.", "रीण आनी त्रासांतल्यान सुट मेळोवपा खातीर एक दुआ."),
        "dua_sleep_fear" to DuaText("न्हीद येतना भंय वा अस्वस्थताय", "हांव अल्लाहच्या परिपूर्ण उतरांचो आलाशिरो ताच्या राग आनी ख्यास्त, ताच्या सेवकांच्या वायटपणां पसून, भुताच्या कुजबुज्यां पसून आनी म्हजे कडेन येवपा पसून मागता.", "न्हिदतना भंय वा अस्वस्थताय जाणवता तेन्ना.", "अशें केल्यार ताका लुकसाण जावचें ना."),
        "dua_waking_afani" to DuaText("जागप-ताणें म्हजो आत्मा परतून मेळयलो", "सगळ्यो तोखणाय अल्लाहाक आसा, जाणें म्हज्या कुडीची तब्येत बरी केली, म्हजो आत्मा म्हजे कडेन परत दिलो आनी म्हाका ताची याद दवरपाक दिली.", "जागतना.", "नव्या सकाळीक उपकार."),
        "dua_allahu_rabbi" to DuaText("अल्लाह, अल्लाह म्हजो प्रभू आसा.", "अल्लाह, अल्लाह हो म्हजो प्रभू; हांव ताचे कडेन कसलोच संबंद जोडना.", "दुख्ख वा त्रासांत-पैगंबर सल्ल्याह अलियाह वसलमान अस्मा बिंत उमायस (आर. ए.) हाका तें शिकयलें.", "संकटाच्या वेळार तौहिद धरचो."),
    )
}
